), u as (
  update lulusan l set nis=coalesce(l.nis,d.nis), peserta_upk=coalesce(l.peserta_upk,d.peserta_upk)
  from d where l.nisn=d.nisn returning l.nisn
)
insert into lulusan(nama,nis,nisn,peserta_upk,tempat_lahir,tgl_lahir,ortu,jenjang,tahun_lulus,no_ijazah,status,catatan)
select d.nama,d.nis,d.nisn,d.peserta_upk,d.tempat_lahir,d.tgl_lahir::date,d.ortu,d.jenjang,d.tahun_lulus::int,d.no_ijazah,'lulus',d.catatan
from d where not exists (select 1 from lulusan l where l.nisn=d.nisn)
  and (d.no_ijazah is null or not exists (select 1 from lulusan l where l.no_ijazah=d.no_ijazah));
